import{c as a,Q as e,j as s,m as n}from"./chunks/framework.DOi4mjdC.js";const h=JSON.parse('{"title":"Duplicate","description":"","frontmatter":{},"headers":[{"level":1,"title":"Duplicate","slug":"duplicate"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/Memory矢量计算/数据填充/Duplicate.md","filePath":"api/SIMD-API/基础API/Memory矢量计算/数据填充/Duplicate.md"}'),l={name:"api/SIMD-API/基础API/Memory矢量计算/数据填充/Duplicate.md"};function i(p,t,d,o,c,r){return e(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="duplicate" tabindex="-1">Duplicate <a class="header-anchor" href="#duplicate" aria-label="Permalink to &quot;Duplicate&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>√</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>√</td></tr><tr><td>Kirin X90</td><td>√</td></tr><tr><td>Kirin 9030</td><td>√</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>将一个变量或立即数复制多次并填充到向量中。</p><p>针对Ascend 950PR/Ascend 950DT，为方便开发者使用，tensor前n个数据计算接口同时也支持直接传入Tensor，此时会将Tensor的第一个元素复制多次并填充到向量中。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><ul><li><p>tensor前n个数据计算</p><ul><li><p>源操作数为标量</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T&gt;</span></span>
<span class="line"><span>__aicore__ inline void Duplicate(const LocalTensor&lt;T&gt;&amp; dst, const T&amp; scalarValue, const int32_t&amp; count)</span></span></code></pre></div></li><li><p>源操作数为Tensor</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T&gt;</span></span>
<span class="line"><span>__aicore__ inline void Duplicate(const LocalTensor&lt;T&gt;&amp; dst, const LocalTensor&lt;T&gt;&amp; src, const int32_t&amp; count)</span></span></code></pre></div></li></ul></li><li><p>tensor高维切分计算</p><ul><li><p>mask逐比特模式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, bool isSetMask = true&gt;</span></span>
<span class="line"><span>__aicore__ inline void Duplicate(const LocalTensor&lt;T&gt;&amp; dst, const T&amp; scalarValue, uint64_t mask[], const uint8_t repeatTime, const uint16_t dstBlockStride, const uint8_t dstRepeatStride)</span></span></code></pre></div></li><li><p>mask连续模式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, bool isSetMask = true&gt;</span></span>
<span class="line"><span>__aicore__ inline void Duplicate(const LocalTensor&lt;T&gt;&amp; dst, const T&amp; scalarValue, uint64_t mask, const uint8_t repeatTime, const uint16_t dstBlockStride, const uint8_t dstRepeatStride)</span></span></code></pre></div></li></ul></li></ul><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>操作数数据类型。 Ascend 950PR/Ascend 950DT，支持的数据类型为：bool、int8_t、uint8_t、fp4x2_e2m1_t、fp4x2_e1m2_t、 hifloat8_t、fp8_e5m2_t、fp8_e4m3fn_t、 fp8_e8m0_t、int16_t、uint16_t、half、bfloat16_t、int32_t、uint32_t、float、complex32、int64_t、uint64_t、complex64。 Atlas A3 训练系列产品/Atlas A3 推理系列产品，支持的数据类型为：int16_t、uint16_t、half、bfloat16_t、int32_t、uint32_t、float。 Atlas A2 训练系列产品/Atlas A2 推理系列产品，支持的数据类型为：int16_t、uint16_t、half、bfloat16_t、int32_t、uint32_t、float。 Atlas 200I/500 A2 推理产品，支持的数据类型为：int16_t、uint16_t、half、int32_t、uint32_t、float。 Atlas 推理系列产品AI Core，支持的数据类型为：int16_t、uint16_t、half、int32_t、uint32_t、float。 Atlas 训练系列产品，支持的数据类型为：int16_t、uint16_t、half、int32_t、uint32_t、float。 Kirin X90，支持的数据类型为：half。 Kirin 9030，支持的数据类型为：half。</td></tr><tr><td>isSetMask</td><td>是否在接口内部设置mask。 true，表示在接口内部设置mask。false，表示在接口外部设置mask，开发者需要使用SetVectorMask接口设置mask值。这种模式下，接口入参中的mask值设置为占位符MASK_PLACEHOLDER，用于占位，无实际含义。</td></tr></tbody></table><p><strong>表 2</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 LocalTensor的起始地址需要32字节对齐。</td></tr><tr><td>scalarValue</td><td>输入</td><td>被复制的源操作数，数据类型需与dst中元素的数据类型保持一致。</td></tr><tr><td>src</td><td>输入</td><td>类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 数据类型需与dst中元素的数据类型保持一致。 当传入该参数时，会将src[0]复制多次并填充到向量中。</td></tr><tr><td>count</td><td>输入</td><td>参与计算的元素个数。</td></tr><tr><td>mask/mask[]</td><td>输入</td><td>mask用于控制每次迭代内参与计算的元素。 逐bit模式：可以按位控制哪些元素参与计算，bit位的值为1表示参与计算，0表示不参与。 mask为数组形式，数组长度和数组元素的取值范围和操作数的数据类型有关。当操作数为16位时，数组长度为2，mask[0]、mask[1]∈[0, 264-1]并且不同时为0；当操作数为32位时，数组长度为1，mask[0]∈(0, 264-1]；当操作数为64位时，数组长度为1，mask[0]∈(0, 232-1]。 例如，mask=[8, 0]，8=0b1000，表示仅第4个元素参与计算。 连续模式：表示前面连续的多少个元素参与计算。取值范围和操作数的数据类型有关，数据类型不同，每次迭代内能够处理的元素个数最大值不同。当操作数为16位时，mask∈[1, 128]；当操作数为32位时，mask∈[1, 64]；当操作数为64位时，mask∈[1, 32]。</td></tr><tr><td>repeatTime</td><td>输入</td><td>矢量计算单元，每次读取连续的8个datablock（每个block32Bytes，共256Bytes）数据进行计算，为完成对输入数据的处理，必须通过多次迭代（repeat）才能完成所有数据的读取与计算。repeatTime表示迭代的次数。</td></tr><tr><td>dstBlockStride</td><td>输入</td><td>单次迭代内，矢量目的操作数不同datablock间地址步长。</td></tr><tr><td>dstRepeatStride</td><td>输入</td><td>相邻迭代间，矢量目的操作数相同datablock地址步长。</td></tr></tbody></table><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>操作数地址对齐要求请参见<a href="./../../../通用说明和约束.html#section796754519912">通用地址对齐约束</a>。</li><li>针对Ascend 950PR/Ascend 950DT，bool、int8_t、uint8_t、fp4x2_e2m1_t、fp4x2_e1m2_t、hifloat8_t、fp8_e5m2_t、fp8_e4m3fn_t、 fp8_e8m0_t、complex32、int64_t、uint64_t、complex64数据类型仅支持tensor前n个数据计算接口。</li></ul><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>本示例仅展示Compute流程的部分代码。如需运行，请将代码段复制并粘贴到<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/02_features/03_basic_api/02_memory_vector_compute/duplicate" target="_blank" rel="noreferrer">Duplicate样例</a>中的Compute函数对应位置。</p><ul><li><p>tensor高维切分计算样例-mask连续模式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uint64_t mask = 128;</span></span>
<span class="line"><span>half scalar = 18.0;</span></span>
<span class="line"><span>// repeatTime = 2, 128 elements one repeat, 256 elements total</span></span>
<span class="line"><span>// dstBlkStride = 1, no gap between blocks in one repeat</span></span>
<span class="line"><span>// dstRepStride = 8, no gap between repeats</span></span>
<span class="line"><span>AscendC::Duplicate(dstLocal, scalar, mask, 2, 1, 8 );</span></span></code></pre></div></li><li><p>tensor高维切分计算样例-mask逐bit模式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uint64_t mask[2] = { UINT64_MAX, UINT64_MAX };</span></span>
<span class="line"><span>half scalar = 18.0;</span></span>
<span class="line"><span>// repeatTime = 2, 128 elements one repeat, 256 elements total</span></span>
<span class="line"><span>// dstBlkStride = 1, no gap between blocks in one repeat</span></span>
<span class="line"><span>// dstRepStride = 8, no gap between repeats</span></span>
<span class="line"><span>AscendC::Duplicate(dstLocal, scalar, mask, 2, 1, 8 );</span></span></code></pre></div></li><li><p>tensor前n个数据计算样例，源操作数为标量</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>half inputVal(18.0);</span></span>
<span class="line"><span>int32_t srcDataSize = 256; // 参与计算的元素个数</span></span>
<span class="line"><span>AscendC::Duplicate&lt;half&gt;(dstLocal, inputVal, srcDataSize);</span></span></code></pre></div></li><li><p>tensor前n个数据计算样例，源操作数为Tensor</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AscendC::Duplicate&lt;half&gt;(dstLocal, srcLocal, srcDataSize);</span></span></code></pre></div></li></ul><p>结果示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>scalar: 18.0</span></span>
<span class="line"><span>srcLocal: [18.0 1.0 2.0 ... 254.0 255.0]</span></span>
<span class="line"><span>dstLocal: [18.0 18.0 18.0 ... 18.0 18.0]</span></span></code></pre></div>`,22)])])}const _=a(l,[["render",i]]);export{h as __pageData,_ as default};
